import {projectedBuildingSurfaces,pickBuildingSurface,paintPickedSurfaces,samplePickedSurface} from './building-surface-picking.js?v=business-site-analysis-2';
import {BUILDING_MATERIALS,SURFACE_NAMES} from './building-materials.js?v=business-site-analysis-2';
export function mountBuildingPreviewPaint(canvas,{get,camera,apply,render,mode,material,status}){
 const base=Object.fromEntries(['onpointerdown','onpointermove','onpointerup','onpointercancel','onkeydown','onwheel'].map(k=>[k,canvas[k]]));let hover=null,stroke=null,geometry=null;
 const point=e=>{const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};
 function surfaces(){const d=get(),key=[d.blocks,d.voxels,d.footprint,d.rotation];if(!geometry||key.some((v,i)=>v!==geometry.key[i]))geometry={key,faces:projectedBuildingSurfaces(d,d.rotation)};return geometry.faces;}
 const pick=p=>pickBuildingSurface(surfaces(),p,camera());
 function message(face){status.textContent=face?`${SURFACE_NAMES[face.side]} · column ${face.x+1}, row ${face.y+1}. Paint applies to this column and side across its layers.`:'Point at a visible model surface. Choose a block layout or independent layers before painting.';}
 function act(face){if(!face){message(null);return;}if(mode.value==='sample'){material.value=String(samplePickedSurface(get().materials,face));status.textContent=`Selected ${BUILDING_MATERIALS[Number(material.value)]}. The building is unchanged.`;}else{apply(paintPickedSurfaces(get().materials,[face],Number(material.value)));message(face);}}
 function cancel(){stroke=null;render();}
 mode.onchange=()=>{stroke=null;hover=null;base.onpointercancel?.();canvas.style.cursor=mode.value==='pan'?'grab':'crosshair';render();};material.onchange=cancel;
 canvas.onpointerdown=e=>{if(mode.value==='pan')return base.onpointerdown?.(e);if(e.button!==0)return;e.preventDefault();canvas.focus({preventScroll:true});hover=point(e);const face=pick(hover);if(mode.value==='sample'){act(face);render();return;}const d=get();stroke={id:e.pointerId,blocks:d.blocks,voxels:d.voxels,footprint:d.footprint,rotation:d.rotation,camera:JSON.stringify(camera()),faces:new Map()};if(face)stroke.faces.set(face.index*5+face.side,face);canvas.setPointerCapture(e.pointerId);message(face);render();};
 canvas.onpointermove=e=>{if(mode.value==='pan')return base.onpointermove?.(e);hover=point(e);const face=pick(hover);if(stroke?.id===e.pointerId&&face)stroke.faces.set(face.index*5+face.side,face);message(face);render();};
 canvas.onpointerup=e=>{if(mode.value==='pan')return base.onpointerup?.(e);if(stroke?.id!==e.pointerId)return;const current=stroke;stroke=null;const d=get();if(!e.shiftKey&&d.blocks===current.blocks&&d.voxels===current.voxels&&d.footprint===current.footprint&&d.rotation===current.rotation&&JSON.stringify(camera())===current.camera&&current.faces.size)apply(paintPickedSurfaces(d.materials,[...current.faces.values()],Number(material.value)));render();};
 canvas.onpointercancel=e=>{if(mode.value==='pan')return base.onpointercancel?.(e);cancel();};
 canvas.onwheel=e=>{stroke=null;base.onwheel?.(e);};
 canvas.onkeydown=e=>{if(mode.value!=='pan'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter',' '].includes(e.key)){e.preventDefault();e.stopPropagation();stroke=null;hover??={x:128,y:300};const step=e.shiftKey?24:8;if(e.key==='ArrowLeft')hover.x-=step;if(e.key==='ArrowRight')hover.x+=step;if(e.key==='ArrowUp')hover.y-=step;if(e.key==='ArrowDown')hover.y+=step;if(e.key==='Enter'||e.key===' ')act(pick(hover));else message(pick(hover));render();return;}if(e.key==='Escape'&&stroke){e.preventDefault();e.stopPropagation();cancel();return;}stroke=null;base.onkeydown?.(e);};
 return{reset(){stroke=null;hover=null;geometry=null;},draw(ctx){if(mode.value==='pan')return;canvas.style.cursor='crosshair';const face=hover?pick(hover):null;const selected=new Set(stroke?[...stroke.faces.keys()]:face?[face.index*5+face.side]:[]);ctx.save();ctx.strokeStyle='#ffe180';ctx.lineWidth=1.2/camera().zoom;for(const f of surfaces())if(selected.has(f.index*5+f.side)){ctx.beginPath();f.polygon.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.stroke();}if(hover){const c=camera(),x=(hover.x-c.x)/c.zoom,y=(hover.y-c.y)/c.zoom;ctx.beginPath();ctx.moveTo(x-3/c.zoom,y);ctx.lineTo(x+3/c.zoom,y);ctx.moveTo(x,y-3/c.zoom);ctx.lineTo(x,y+3/c.zoom);ctx.stroke();}ctx.restore();}};
}
